// Storm instances observed in the last sol before replay time T (same units as row t), via binary search
// ponytail: one MDAD instance per storm per sol; 0.54 deg Ls ~= one sol
window.stormsAt = (T, win = 0.54) => {
  const S = window.STORMS;
  let lo = 0, hi = S.length;
  while (lo < hi) { const m = (lo + hi) >> 1; if (S[m][0] <= T - win) lo = m + 1; else hi = m; }
  const out = [];
  for (let i = lo; i < S.length && S[i][0] <= T; i++) out.push(S[i]);
  return out;
};
// Great-circle distance (km) on Mars between two lat/lon points in degrees
window.marsKm = (lat1, lon1, lat2, lon2) => {
  const r = Math.PI / 180, a = Math.sin((lat2 - lat1) * r / 2) ** 2 +
    Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin((lon2 - lon1) * r / 2) ** 2;
  return 2 * 3389.5 * Math.asin(Math.min(1, Math.sqrt(a)));
};
// Storm instances per Mars year whose area covered (lat, lon), over the whole record
window.stormRisk = (lat, lon) => {
  let n = 0;
  for (const s of window.STORMS) if (window.marsKm(lat, lon, s[2], s[1]) < s[3]) n++;
  return n / 9; // MY24..MY32
};
console.assert(Math.abs(window.marsKm(0, 0, 0, 180) - Math.PI * 3389.5) < 1, 'marsKm half circumference');
console.assert(window.stormsAt(window.STORMS[100][0]).includes(window.STORMS[100]), 'stormsAt finds a row at its own time');
